func rob(nums []int) int {
	if len(nums) == 0 {
		return 0
	}
	// 子问题：
	// f(k) = 偷 [0..k) 房间中的最大金额
	// f(0) = 0
	// f(1) = nums[0]
	// f(k) = max{ rob(k-1), nums[k-1] + rob(k-2) }
	N := len(nums)
	dp := make([]int, N+1)
	dp[0] = 0
	dp[1] = nums[0]
	for k := 2; k <= N; k++ {
		if dp[k-1] > nums[k-1]+dp[k-2] {
			dp[k] = dp[k-1]
		} else {
			dp[k] = nums[k-1] + dp[k-2]
		}
	}
	return dp[N]
}

func rob(nums []int) int {
	prev, curr := 0, 0
	// 每次循环，计算"偷到当前房子为止的最大金额"
	for _, i := range nums {
		// 循环开始时，curr 表示 dp[k-1]，prev 表示 dp[k-2]
		// dp[k] = max{ dp[k-1], dp[k-2] + i }
		tmp := curr
		if prev+i > curr {
			curr = prev + i
		}
		prev = tmp
		// 循环结束时，curr 表示 dp[k]，prev 表示 dp[k-1]
	}
	return curr
}
